function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n must be between 1 and 100000.';
  if (!Array.isArray(edges) || edges.length > 200000) return 'edges holds at most 200000 pairs.';
  const used = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints must be nodes 0 to n - 1.';
    if (a === b) return 'An edge cannot join a node to itself.';
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (used.has(key)) return 'The same edge appears twice.';
    used.add(key);
  }
  return null;
}

