function countPairs(n, edges) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  const visited = new Array(n).fill(false);
  let pairs = 0;
  let seenSoFar = 0;
  for (let start = 0; start < n; start++) {
    if (visited[start]) {
      continue;
    }
    visited[start] = true;
    const stack = [start];
    let size = 0;
    while (stack.length > 0) {
      const node = stack.pop();
      size++;
      for (const next of graph[node]) {
        if (!visited[next]) {
          visited[next] = true;
          stack.push(next);
        }
      }
    }
    pairs += size * seenSoFar;
    seenSoFar += size;
  }
  return pairs;
}

