function countPairs(n, edges) {
  // Union-find groups the nodes; then all pairs minus the pairs inside each group.
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (parent[x] !== x) x = parent[x] = parent[parent[x]]; return x; };
  for (const [a, b] of edges) parent[find(a)] = find(b);
  const count = new Map();
  for (let i = 0; i < n; i++) count.set(find(i), (count.get(find(i)) || 0) + 1);
  let together = 0;
  for (const c of count.values()) together += c * (c - 1) / 2;
  return n * (n - 1) / 2 - together;
}

