function generate(rand, size) {
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? 1500 + Math.floor(rand() * 501) : 2000 + Math.floor(rand() * 98001)) : 1 + Math.floor(rand() * 8);
  const groups = large ? 1 + Math.floor(rand() * 60) : 1 + Math.floor(rand() * 4);
  const group = Array.from({ length: n }, () => Math.floor(rand() * groups));
  const target = large ? 1000 + Math.floor(rand() * 1001) : Math.floor(rand() * (n * (n - 1) / 2 + 1));
  const edges = [], used = new Set();
  // Edges only join nodes of the same group, so several components appear; attempts are capped.
  for (let attempt = 0; attempt < target * 10 + 20 && edges.length < target; attempt++) {
    const a = Math.floor(rand() * n), b = Math.floor(rand() * n);
    if (a === b || group[a] !== group[b]) continue;
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (used.has(key)) continue;
    used.add(key);
    edges.push([a, b]);
  }
  return [n, edges];
}
